# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def make(last, first):
    return Student("id", last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_rows(self):
        people = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Zeller", "Anna")
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zeller, Anna"
            ]
        )

    def test_bad_seat_count(self):
        people = [make("Dunmere", "Piet")]
        for seats in (0, -1):
            with self.assertRaises(ProjectError):
                seating_rows(people, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)
